from collections import Counter

recs = {}
name=None; seq=[]
for line in open('region.fasta'):
    line=line.strip()
    if line.startswith('>'):
        name=line[1:]; recs[name]=[]
    elif line:
        recs[name].append(line)
seq=''.join(recs[name])
L=len(seq)
print('ID:', name)
print('Length:', L)
c=Counter(seq.upper())
print('Composition:', {k:c.get(k,0) for k in 'ACGTN'})
gc=(c.get('G',0)+c.get('C',0))/L*100
print('GC%%: %.1f' % gc)
print('Count of "A"*8+:', len(re.findall(r'A{8,}', seq)), '| T{8,}:', len(re.findall(r'T{8,}', seq)))

def rc(s):
    return s.translate(str.maketrans('ACGT','TGCA'))[::-1]

STOPS={'TAA','TAG','TGA'}
def codons(s):
    return [s[i:i+3] for i in range(0, len(s)-len(s)%3, 3)]

def frame(orfs, strand, strandseq, frameidx, offset):
    cs=codons(strandseq)
    i=0
    while i < len(cs):
        if cs[i]=='ATG':
            j=i
            while j<len(cs) and cs[j] not in STOPS:
                j+=1
            if j<len(cs):
                n=j-i
                orfs.append({'start':strand, 'stop':strand, 'gin':offset+frameidx+3*i+1,
                             'gout':offset+frameidx+3*(j-1)+3, 'len':n, 'codons':cs[i:j][:5]})
            i=j
        else:
            i+=1

orfs=[]
for s in ('+','-'):
    ss=seq.upper() if s=='+' else rc(seq.upper())
    for f in range(3):
        frame(orfs, s, ss, f, 0)
orfs.sort(key=lambda o:-o['len'])
print('\nLONGEST STOP-TO-STOP ORFs (6 frames):')
for o in orfs[:12]:
