def find_orfs(s, label, min_codons=60):
    found=[]
    for f in range(3):
        i=f
        while i+3<=len(s):
            if s[i:i+3]=='ATG':
                j=i
                while j+3<=len(s) and s[j:j+3] not in STOPS:
                    j+=3
